sample:
# 「variable の数と resource の数の比」で流儀を推測するロジックです。

locals {
  # あるモジュールを読解してカウントした結果とします
  input_count    = 14 # variable の数
  resource_count = 1  # resource の数

  # resource が入力より多ければ「厚い」、少なければ「薄い」と推測
  style = local.resource_count > local.input_count ? "thick" : "thin"
}

output "style" {
  value = local.style
}

exercise.starter:
locals {
  modules = {
    # ここに 2 つのモジュールの読解メモを書く
  }
}

# ここに for 式と output を書く

exercise.answer:
locals {
  modules = {
    s3_bucket = { inputs = 14, resources = 1 }  # 入力が多くリソース 1 個 → 薄い
    vpc       = { inputs = 4, resources = 12 }  # 入力が少なくリソース多数 → 厚い
  }

  # マップへの for 式は k(キー), v(値) の 2 変数で回り、キーのアルファベット順になります
  styles = [for k, v in local.modules : "${k}:${v.resources > v.inputs ? "thick" : "thin"}"]
}

output "styles" {
  value = join(", ", local.styles)
}
